import { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { Check, Copy } from 'lucide-react';

interface CodeBlockProps {
  language: string;
  code: string;
}

export function CodeBlock({ language, code }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback if clipboard API is restricted
      const textarea = document.createElement('textarea');
      textarea.value = code;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="my-3 overflow-hidden rounded-[10px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_5%,transparent)] text-[13px] shadow-sm">
      <div className="flex items-center justify-between border-b border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] px-3.5 py-1.5">
        <span className="font-mono text-[11px] font-medium uppercase tracking-wider text-[var(--text-muted)]">
          {language || 'code'}
        </span>
        <button
          type="button"
          onClick={handleCopy}
          aria-label={copied ? 'Copied code' : 'Copy code to clipboard'}
          className="inline-flex cursor-pointer items-center gap-1.5 rounded-[5px] px-2 py-0.5 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
        >
          {copied ? (
            <>
              <Check size={12} strokeWidth={2} className="text-emerald-400" />
              <span className="text-emerald-400">Copied</span>
            </>
          ) : (
            <>
              <Copy size={12} strokeWidth={1.5} />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>
      <pre className="scroll-soft overflow-x-auto p-3.5 font-mono leading-relaxed text-[var(--text)]">
        <code>{code}</code>
      </pre>
    </div>
  );
}

interface MarkdownContentProps {
  content: string;
  className?: string;
}

export function MarkdownContent({ content, className = '' }: MarkdownContentProps) {
  return (
    <div className={`break-words ${className}`}>
      <ReactMarkdown
        components={{
          code({ className: codeClass, children, ...props }) {
            const match = /language-(\w+)/.exec(codeClass || '');
            const raw = String(children ?? '');
            const isBlock = Boolean(match) || raw.includes('\n');
            if (isBlock) {
              const codeString = raw.replace(/\n$/, '');
              return <CodeBlock language={match ? match[1] : ''} code={codeString} />;
            }
            return (
              <code
                className="rounded-[4px] bg-[color-mix(in_srgb,var(--text)_8%,transparent)] px-1.5 py-0.5 font-mono text-[0.88em]"
                {...props}
              >
                {children}
              </code>
            );
          },
          p({ children }) {
            return <p className="mb-2.5 last:mb-0 leading-relaxed">{children}</p>;
          },
          ul({ children }) {
            return <ul className="mb-2.5 list-disc pl-5 space-y-1">{children}</ul>;
          },
          ol({ children }) {
            return <ol className="mb-2.5 list-decimal pl-5 space-y-1">{children}</ol>;
          },
          li({ children }) {
            return <li className="leading-relaxed">{children}</li>;
          },
          h1({ children }) {
            return <h1 className="mb-2 mt-4 text-[1.25em] font-semibold tracking-tight">{children}</h1>;
          },
          h2({ children }) {
            return <h2 className="mb-2 mt-3 text-[1.15em] font-semibold tracking-tight">{children}</h2>;
          },
          h3({ children }) {
            return <h3 className="mb-1.5 mt-2.5 text-[1.05em] font-medium tracking-tight">{children}</h3>;
          },
          blockquote({ children }) {
            return (
              <blockquote className="my-2.5 border-l-2 border-[var(--border-strong)] pl-3 italic text-[var(--text-muted)]">
                {children}
              </blockquote>
            );
          },
          a({ href, children }) {
            return (
              <a
                href={href}
                target="_blank"
                rel="noreferrer noopener"
                className="underline underline-offset-2 decoration-[var(--border-strong)] transition-colors hover:text-[var(--text)]"
              >
                {children}
              </a>
            );
          },
          table({ children }) {
            return (
              <div className="my-3 overflow-x-auto">
                <table className="min-w-full divide-y divide-[var(--border)] text-[13px] border border-[var(--border)] rounded-[8px]">
                  {children}
                </table>
              </div>
            );
          },
          th({ children }) {
            return (
              <th className="px-3 py-2 text-left font-semibold text-[var(--text)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)]">
                {children}
              </th>
            );
          },
          td({ children }) {
            return <td className="px-3 py-2 text-[var(--text-muted)] border-t border-[var(--border)]">{children}</td>;
          },
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
}

export default MarkdownContent;

import { useState } from 'react';
import {
  ChevronDown,
  Sparkles,
  Terminal,
  FileText,
  Globe,
  CheckCircle2,
  XCircle,
  ShieldAlert,
  Archive,
  RotateCw,
} from 'lucide-react';
import type { RunStepEvent, RunStepType } from '@/types';

interface Props {
  active: boolean;
  steps?: RunStepEvent[];
  summary?: string;
}

function getToolIcon(toolName: string) {
  switch (toolName) {
    case 'bash':
      return <Terminal size={14} className="text-sky-400" />;
    case 'read':
    case 'write':
    case 'edit':
      return <FileText size={14} className="text-emerald-400" />;
    case 'web_search':
    case 'web_fetch':
      return <Globe size={14} className="text-purple-400" />;
    default:
      return <Sparkles size={14} className="text-amber-400" />;
  }
}

function StepRow({ step }: { step: RunStepEvent }) {
  const [expanded, setExpanded] = useState(false);
  const { event_type, payload } = step;

  if (event_type === 'thought') {
    const content = typeof payload.content === 'string' ? payload.content.trim() : '';
    return (
      <li className="space-y-1.5 rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-2.5 text-[12px]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 font-medium text-[var(--text)]">
            <Sparkles size={13} className="text-amber-400" />
            <span>Reasoning</span>
            {payload.total_tokens ? (
              <span className="text-[10px] text-[var(--text-muted)] tabular-nums">
                ({String(payload.total_tokens)} tokens)
              </span>
            ) : null}
          </div>
          {content ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 text-[11px] text-[var(--text-muted)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide' : 'Details'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>
        {content && (expanded || content.length < 120) ? (
          <p className="font-serif italic leading-relaxed text-[var(--text-muted)] whitespace-pre-wrap">
            {content}
          </p>
        ) : content ? (
          <p className="line-clamp-2 font-serif italic text-[var(--text-muted)]">
            {content}
          </p>
        ) : null}
      </li>
    );
  }

  if (event_type === 'tool_call') {
    const toolName = String(payload.tool_name ?? 'tool');
    const args = (payload.arguments ?? {}) as Record<string, unknown>;
    const command = typeof args.command === 'string' ? args.command : null;
    const path = typeof args.path === 'string' ? args.path : null;
    const query = typeof args.query === 'string' ? args.query : null;

    return (
      <li className="space-y-1.5 rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-2.5 text-[12px]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 font-medium text-[var(--text)]">
            {getToolIcon(toolName)}
            <span className="font-mono text-[11px] uppercase tracking-wider">{toolName}</span>
            <span className="rounded bg-[color-mix(in_srgb,var(--text)_8%,transparent)] px-1.5 py-0.5 text-[10px] text-[var(--text-muted)]">
              Tool Call
            </span>
          </div>
          {Object.keys(args).length > 0 ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 text-[11px] text-[var(--text-muted)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide args' : 'View args'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>

        {command ? (
          <div className="rounded-[6px] bg-[color-mix(in_srgb,var(--text)_6%,transparent)] p-2 font-mono text-[11px] text-[var(--text)]">
            <span className="text-[var(--text-muted)]">$ </span>
            {command}
          </div>
        ) : path ? (
          <div className="font-mono text-[11px] text-[var(--text-muted)]">
            Path: <span className="text-[var(--text)]">{path}</span>
          </div>
        ) : query ? (
          <div className="text-[11px] text-[var(--text-muted)]">
            Query: <span className="text-[var(--text)] font-medium">&ldquo;{query}&rdquo;</span>
          </div>
        ) : null}

        {expanded ? (
          <pre className="scroll-soft overflow-x-auto rounded-[6px] bg-[color-mix(in_srgb,var(--text)_6%,transparent)] p-2 font-mono text-[10px] text-[var(--text-muted)]">
            {JSON.stringify(args, null, 2)}
          </pre>
        ) : null}
      </li>
    );
  }

  if (event_type === 'tool_result') {
    const toolName = String(payload.tool_name ?? 'tool');
    const result = payload.result;
    const isError =
      (typeof result === 'object' && result !== null && 'error' in result) ||
      (typeof result === 'string' && result.toLowerCase().includes('error'));

    return (
      <li className="space-y-1.5 rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-2.5 text-[12px]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {isError ? (
              <XCircle size={13} className="text-rose-400" />
            ) : (
              <CheckCircle2 size={13} className="text-emerald-400" />
            )}
            <span className="font-medium text-[var(--text)]">Result</span>
            <span className="font-mono text-[11px] text-[var(--text-muted)]">({toolName})</span>
          </div>
          {result !== undefined ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 text-[11px] text-[var(--text-muted)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide output' : 'View output'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>

        {expanded && result !== undefined ? (
          <pre className="scroll-soft max-h-48 overflow-y-auto rounded-[6px] bg-[color-mix(in_srgb,var(--text)_6%,transparent)] p-2 font-mono text-[10px] text-[var(--text)]">
            {typeof result === 'object' ? JSON.stringify(result, null, 2) : String(result)}
          </pre>
        ) : null}
      </li>
    );
  }

  if (event_type === 'approval_required') {
    return (
      <li className="flex items-center gap-2 rounded-[8px] border border-amber-500/30 bg-amber-500/10 p-2.5 text-[12px] text-amber-200">
        <ShieldAlert size={14} className="text-amber-400 shrink-0" />
        <span>Action required: approval requested for execution</span>
      </li>
    );
  }

  if (event_type === 'compaction') {
    return (
      <li className="flex items-center gap-2 rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-2 text-[11px] text-[var(--text-muted)]">
        <Archive size={13} className="shrink-0" />
        <span>Context window compacted for optimal tokens</span>
      </li>
    );
  }

  return null;
}

export function ThinkingCapsule({ active, steps = [], summary }: Props) {
  const [open, setOpen] = useState(false);
  if (!active && steps.length === 0) return null;

  // Filter out streaming delta chunks from the semantic timeline
  const semanticSteps = steps.filter((s) => s.event_type !== 'message_delta');
  const latestStep = semanticSteps[semanticSteps.length - 1];

  let displaySummary = summary;
  if (!displaySummary) {
    if (active) {
      if (latestStep?.event_type === 'tool_call') {
        const tool = String(latestStep.payload.tool_name ?? 'tool');
        displaySummary = `Running ${tool}...`;
      } else if (latestStep?.event_type === 'tool_result') {
        displaySummary = 'Processing tool results...';
      } else {
        displaySummary = semanticSteps.length > 0 ? `Thinking & executing (${semanticSteps.length} steps)...` : 'Thinking it through...';
      }
    } else {
      displaySummary = `Completed execution (${semanticSteps.length} steps)`;
    }
  }

  return (
    <div className="mb-4" role="status">
      <div className="glass inline-flex flex-col rounded-[10px] border border-[var(--border)] overflow-hidden transition-all duration-300 max-w-xl">
        <button
          type="button"
          onClick={() => setOpen((o) => !o)}
          aria-expanded={open}
          className="flex cursor-pointer items-center justify-between gap-3 px-3.5 py-2 text-[13px] font-medium text-[var(--text-muted)] hover:text-[var(--text)] transition-colors"
        >
          <div className="flex items-center gap-2.5">
            {active ? (
              <RotateCw size={13} strokeWidth={2} className="animate-spin text-sky-400" />
            ) : (
              <Sparkles size={13} className="text-amber-400" />
            )}
            <span>{displaySummary}</span>
          </div>
          {semanticSteps.length > 0 ? (
            <ChevronDown
              size={14}
              strokeWidth={1.5}
              className={`transition-transform duration-300 ease-spring ${open ? 'rotate-180' : ''}`}
            />
          ) : null}
        </button>

        {open && semanticSteps.length > 0 ? (
          <div className="border-t border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_2%,transparent)] p-3">
            <ul className="space-y-2">
              {semanticSteps.map((step, i) => (
                <StepRow key={`${step.step_number}-${i}`} step={step} />
              ))}
            </ul>
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default ThinkingCapsule;

